import 'package:flutter/material.dart';

/// ORO GEM Tech Irrigation Automations logo.
///
/// Pure-vector [CustomPainter] traced directly from the supplied logo PNG,
/// so it matches the artwork shape-for-shape (gear, crescent, leaves, GEM
/// letters, circuit lines, tagline) and stays sharp at any size.
///
/// Usage:
///   GemLogoWidget(height: 80)
///   GemLogoWidget(width: 300)
class GemLogoWidget extends StatelessWidget {
  final double? height;
  final double? width;
  final bool onDark;

  const GemLogoWidget({
    super.key,
    this.height,
    this.width,
    this.onDark = false,
  });

  @override
  Widget build(BuildContext context) {
    final h = height ?? (width != null ? width! / GemLogoPainter.aspect : 50.0);
    final w = width ?? h * GemLogoPainter.aspect;
    return SizedBox(
      width: w,
      height: h,
      child: CustomPaint(
        size: Size(w, h),
        painter: GemLogoPainter(onDark: onDark),
      ),
    );
  }
}

class GemLogoPainter extends CustomPainter {
  final bool onDark;

  const GemLogoPainter({this.onDark = false});

  static const double designWidth = 1366;
  static const double designHeight = 714;
  static const double aspect = designWidth / designHeight;

  static List<_Piece>? _cache;

  @override
  void paint(Canvas canvas, Size size) {
    final pieces = _cache ??= _pieces.map(_Piece.parse).toList(growable: false);

    final scale = size.width / designWidth < size.height / designHeight
        ? size.width / designWidth
        : size.height / designHeight;
    final dx = (size.width - designWidth * scale) / 2;
    final dy = (size.height - designHeight * scale) / 2;

    canvas.save();
    canvas.translate(dx, dy);
    canvas.scale(scale);

    for (final p in pieces) {
      final paint = Paint()
        ..isAntiAlias = true
        ..style = PaintingStyle.fill;

      Color color0 = Color(p.c0);
      Color color1 = Color(p.c1);
      Color midColor = Color(p.mid);

      if (onDark) {
        final r = (p.mid >> 16) & 0xFF;
        final g = (p.mid >> 8) & 0xFF;
        final b = p.mid & 0xFF;

        // If piece is dark navy/gray (text, dark outlines)
        if ((r < 80 && g < 90 && b < 100) ||
            (r < 90 && g < 100 && b < 120 && (r - b).abs() < 30)) {
          midColor = Colors.white;
          color0 = Colors.white;
          color1 = const Color(0xFFE2E8F0);
        }
      }

      if (p.solid) {
        paint.color = midColor;
      } else {
        paint.shader = LinearGradient(
          colors: [color0, color1],
        ).createShader(Rect.fromLTRB(p.x0, p.y0, p.x1, p.y1));
      }
      canvas.drawPath(p.path, paint);
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant GemLogoPainter oldDelegate) => oldDelegate.onDark != onDark;
}

class _Piece {
  final Path path;
  final double x0, y0, x1, y1;
  final int c0, c1, mid;
  final bool solid;

  _Piece(this.path, this.x0, this.y0, this.x1, this.y1, this.c0, this.c1,
      this.mid, this.solid);

  factory _Piece.parse(_Raw r) {
    final path = Path()..fillType = PathFillType.evenOdd;
    final re = RegExp(r'([MLZ])|(-?\d+\.?\d*)');
    final nums = <double>[];
    String? cmd;
    void flush() {
      if (cmd == 'M' && nums.length >= 2) {
        path.moveTo(nums[0], nums[1]);
      } else if (cmd == 'L' && nums.length >= 2) {
        path.lineTo(nums[0], nums[1]);
      } else if (cmd == 'Z') {
        path.close();
      }
      nums.clear();
    }

    for (final m in re.allMatches(r.d)) {
      if (m.group(1) != null) {
        flush();
        cmd = m.group(1);
      } else {
        nums.add(double.parse(m.group(2)!));
        if (nums.length == 2) flush();
      }
    }
    flush();
    return _Piece(path, r.x0.toDouble(), r.y0.toDouble(), r.x1.toDouble(),
        r.y1.toDouble(), r.c0, r.c1, r.cm, r.solid);
  }
}

class _Raw {
  final int x0, y0, x1, y1, c0, c1, cm;
  final bool solid;
  final String d;
  const _Raw(this.x0, this.y0, this.x1, this.y1, this.c0, this.c1, this.cm,
      this.solid, this.d);
}

